/* BrainU for Principles of Robot Autonomy: an unofficial study companion.
 * Two questions build a path through the course; each lesson links to the real
 * lecture, chapter and notebook, checks you with a question, and points on to
 * current research. Preact + htm, no build step; only what changes re-renders.
 * Course data: prototype/course.json, generated by courses/pora/build.py. */
import { h, render } from "preact";
import { useState, useEffect, useLayoutEffect, useRef, useMemo } from "preact/hooks";
import htm from "./vendor/preact/htm.module.js";

const html = htm.bind(h);
const KEY = "brainu-prototype-v1";
const SAVED = ["bg", "goal", "started", "i", "done", "passed", "notes", "wrong", "tick"];
const trunc = (t, n) => (t.length > n ? t.slice(0, n - 1) + "…" : t);
const reduceMotion = () => window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;

// ── course logic ────────────────────────────────────────────────────
function ancestors(C, id) {
  const out = new Set(), st = [...C[id].p];
  while (st.length) { const x = st.pop(); if (!out.has(x)) { out.add(x); st.push(...C[x].p); } }
  return out;
}
// One path covering every goal: what the goals need, minus what you know, in a valid order.
function pathFor(D, bgId, goals) {
  const C = D.C, bg = D.BG.find((b) => b.id === bgId) || D.BG[0], gs = [].concat(goals || []);
  const need = new Set();
  gs.forEach((g) => { need.add(g); ancestors(C, g).forEach((a) => need.add(a)); });
  const keepSet = new Set([...need].filter((x) => gs.includes(x) || !bg.k.includes(x)));
  const chk = (x) => (C[x].c == null ? -1 : C[x].c), order = {}, depth = {};
  Object.keys(C).forEach((k, n) => (order[k] = n));
  const dep = (x) => depth[x] ?? (depth[x] = C[x].p.length ? 1 + Math.max(...C[x].p.map(dep)) : 0);
  const out = [], seen = new Set();
  const visit = (x) => { if (seen.has(x)) return; seen.add(x); C[x].p.filter((p) => keepSet.has(p)).sort((a, b) => chk(a) - chk(b)).forEach(visit); out.push(x); };
  [...keepSet].sort((a, b) => chk(a) - chk(b) || dep(a) - dep(b) || order[a] - order[b]).forEach(visit);
  return { steps: out, known: [...need].filter((x) => !keepSet.has(x)) };
}
const chName = (D, c) => (c == null ? "Assumed background" : c === 0 ? "Getting started" : "Chapter " + c + ": " + D.CH[c].title);
const goalName = (D, id) => (D.G.find((x) => x.id === id) || {}).n || (D.C[id] || {}).n || "";
const goalsLabel = (D, gs) => { const n = gs.map((g) => goalName(D, g)); return n.length <= 2 ? n.join(" + ") : n[0] + " + " + (n.length - 1) + " more"; };
const arxivSearch = (name) => "https://arxiv.org/search/?searchtype=all&order=-announced_date_first&query=" + encodeURIComponent(name.replace(/\(.*?\)/g, "").replace(/&/g, " ").trim() + " robot");

// ── routing: the hash is the page, so Back works ────────────────────
const parse = () => { const [, a = "", b] = location.hash.split("/"); return { page: a, arg: b }; };
const nav = (to) => { if (location.hash !== to) location.hash = to; };

// ── the course map ──────────────────────────────────────────────────
// Every concept as a pin on cork, grouped by part. Used on the front page (lights
// up as you answer) and beside each lesson (your progress). Nodes keep their DOM
// across updates, so only a node whose state changed animates.
const XS = [52, 172, 300, 428, 556], PART_SHORT = ["Background", "Planning & control", "Perception", "Localization", "Decisions"];
function layoutFor(D) {
  const L = {}, ids = Object.keys(D.C);
  D.PARTS.forEach((p, pi) => {
    const mine = ids.filter((id) => p.chs.includes(D.C[id].c)), half = Math.ceil(mine.length / 2), gap = Math.min(30, 300 / Math.max(1, half));
    mine.forEach((id, k) => {
      const sub = mine.length > 6 ? (k < half ? -1 : 1) : 0, row = mine.length > 6 ? k % half : k;
      L[id] = [XS[pi] + sub * 26 + Math.sin(k * 2.1) * 5, 92 + row * gap + (sub > 0 ? gap / 2 : 0) + Math.cos(k * 1.3) * 4];
    });
  });
  return L;
}

function Spark({ from, to }) {
  const ref = useRef();
  useEffect(() => { const a = ref.current && ref.current.querySelector("animateMotion"); if (a && a.beginElement) a.beginElement(); }, []);
  if (reduceMotion()) return null;
  return html`<circle ref=${ref} r="5" class="spark" cx="0" cy="0"><animateMotion begin="indefinite" dur="1s" fill="freeze" path=${`M${from[0]},${from[1]} L${to[0]},${to[1]}`} /></circle>`;
}

function CourseMap({ D, known = [], goals = [], steps = [], current = -1, done = {}, compact = false, pulse = null, onPick }) {
  const L = useMemo(() => layoutFor(D), [D]), ids = Object.keys(D.C), K = new Set(known), at = {};
  steps.forEach((id, k) => (at[id] = k));
  const state = (id) => goals.includes(id) ? "goal" : id in at ? (at[id] === current ? "now" : done[id] ? "done" : "path") : K.has(id) ? "known" : "dim";
  const f = (v) => v.toFixed(1), grow = compact ? 1.45 : 1;
  // Beside a lesson the map zooms to your path so the pins are big enough to read and tap.
  let vb = "0 0 610 420";
  if (compact && steps.length) {
    const pts = steps.concat(goals).filter((id) => L[id]).map((id) => L[id]), xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
    let x0 = Math.min(...xs) - 34, x1 = Math.max(...xs) + 34, y0 = Math.min(...ys) - 34, y1 = Math.max(...ys) + 34;
    const w = Math.max(x1 - x0, 260), hgt = Math.max(y1 - y0, w * 0.62), cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    vb = `${(cx - w / 2).toFixed(0)} ${(cy - hgt / 2).toFixed(0)} ${w.toFixed(0)} ${hgt.toFixed(0)}`;
  }
  const edges = compact ? [] : ids.flatMap((id) => D.C[id].p.filter((q) => L[q]).map((q) => [q, id]));
  return html`<svg class="cmap ${compact ? "cmap-compact" : ""}" viewBox=${vb} role="img"
      aria-label=${steps.length ? `Course map: ${steps.length} lessons on your path${current >= 0 ? ", you are on lesson " + (current + 1) : ""}.` : "Course map of 69 concepts"}>
    ${compact ? null : D.PARTS.map((p, pi) => html`<g key=${"l" + pi} transform=${`translate(${XS[pi]} 44) rotate(${[-2, 1, -1, 2, -1.5][pi]})`}>
      <rect x="-54" y="-14" width="108" height="26" fill="#fbf9f1" /><text y="4" text-anchor="middle" class="gl">${PART_SHORT[pi] || trunc(p.t, 18)}</text></g>`)}
    ${edges.map(([a, b]) => html`<line key=${a + ">" + b} x1=${f(L[a][0])} y1=${f(L[a][1])} x2=${f(L[b][0])} y2=${f(L[b][1])} class=${K.has(a) && K.has(b) ? "ge ge-known" : "ge"} />`)}
    ${steps.slice(1).map((id, k) => { const a = L[steps[k]], b = L[id];
      return html`<line key=${"s" + steps[k] + id} x1=${f(a[0])} y1=${f(a[1])} x2=${f(b[0])} y2=${f(b[1])} class=${"gs " + (current >= 0 && k < current ? "gs-done" : "")} />`; })}
    ${ids.map((id) => { const st = state(id), [x, y] = L[id], k = at[id];
      const r = (st === "goal" ? 8 : st === "now" ? 8 : st === "path" || st === "done" ? 6.5 : st === "known" ? 5 : 3.6) * grow;
      const tip = D.C[id].n + (st === "known" ? " · you know this" : st === "goal" ? " · your goal" : k != null ? " · lesson " + (k + 1) : "");
      const click = onPick && k != null ? () => onPick(k) : null;
      return html`<g key=${id} class=${"gn gn-" + st + (click ? " gn-click" : "")} style=${{ "--d": Math.min(0.6, k != null ? k * 0.05 : (ids.indexOf(id) % 12) * 0.04).toFixed(2) + "s" }}
          onClick=${click} role=${click ? "button" : null} tabindex=${click ? 0 : null} aria-label=${click ? tip : null}
          onKeyDown=${click ? (e) => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), click()) : null}>
        <title>${tip}</title>
        ${st === "goal" || st === "now" ? html`<circle cx=${f(x)} cy=${f(y)} r=${f(r + 5)} class="gn-ring" />` : null}
        <circle cx=${f(x)} cy=${f(y + 1.5)} r=${f(r)} fill="rgba(0,0,0,.25)" />
        <circle cx=${f(x)} cy=${f(y)} r=${f(r)} class="gn-dot" />
        ${(st === "path" || st === "now" || (st === "done" && !compact)) && (!compact || st === "now") ? html`<text x=${f(x)} y=${f(y + (compact ? 4 : 2.6))} text-anchor="middle" class=${compact ? "gn-num-big" : ""}>${k + 1}</text>` : null}
      </g>`; })}
    ${pulse && L[steps[pulse.from]] && L[steps[pulse.from + 1]] ? html`<${Spark} key=${"p" + pulse.key} from=${L[steps[pulse.from]]} to=${L[steps[pulse.from + 1]]} />` : null}
  </svg>`;
}

const Legend = ({ items }) => html`<div class="glegend">${items.map(([cls, t]) => html`<span key=${cls}><i class=${cls}></i>${t}</span>`)}</div>`;

// ── pages ───────────────────────────────────────────────────────────
function TopNav({ page, hasPath }) {
  const link = (to, label, on) => html`<a class="am-nav__link" href=${to} aria-current=${on ? "page" : null}>${label}</a>`;
  return html`<nav class="am-nav top" aria-label="Main">
    <a class="am-nav__brand brand" href="#/">BrainU<small>unofficial companion to Principles of Robot Autonomy</small></a>
    <div class="am-nav__links">
      ${link("#/", "⌂ Home", page === "" || page === "start" || page === "done")}
      ${hasPath ? link("#/path", "My path", page === "path") : null}
      ${hasPath ? link("#/lesson", "Lesson", page === "lesson") : null}
      ${link("#/explore", "Explore", page === "explore")}
    </div></nav>`;
}

function Start({ D, S, set }) {
  const [q, setQ] = useState(S.bg ? 2 : 1);
  const [bg, setBg] = useState(S.bg);
  const [goals, setGoals] = useState(S.goal || []);
  const list = q === 2 ? D.G : D.BG, isOn = (id) => (q === 2 ? goals.includes(id) : bg === id);
  const P = goals.length && bg ? pathFor(D, bg, goals) : { steps: [], known: [] };
  const bgObj = D.BG.find((b) => b.id === bg), nIds = Object.keys(D.C).length;
  const pick = (id) => (q === 2 ? setGoals(isOn(id) ? goals.filter((g) => g !== id) : goals.concat(id)) : setBg(id));
  const go = () => {
    if (q === 1) return setQ(2);
    set({ bg, goal: goals, i: 0, started: false, done: {}, passed: 0, wrong: {}, justBuilt: Date.now() });
    nav("#/path");
  };
  const caption = q === 2 && goals.length ? html`<b>${P.steps.length} lessons</b> pinned for you, strung in order. Next, this becomes your path.`
    : bgObj ? html`You already know <b>${bgObj.k.length}</b> of ${nIds} concepts. ${q === 1 ? "Next: what do you want to do?" : "Now pick what you want to do."}`
    : html`<b>${nIds} concepts</b> in five parts. Answer two questions and watch your part of the course light up.`;
  return html`<main class="start">
    <header class="hero">
      <h1>Your path through <span>Principles of Robot Autonomy</span></h1>
      <p>Tell us what you know and what you want to build. You get the lessons you need, in order, each linked to the course's own lectures, chapters and notebooks.</p>
    </header>
    <div class="start-grid">
      <section class="am-card qcard" data-medium="marker" data-style="notebook" data-theme="light" aria-labelledby="qh">
        <div class="qsteps"><button class=${q === 1 ? "on" : ""} onClick=${() => setQ(1)}>① where you're starting</button><button class=${q === 2 ? "on" : ""} disabled=${!bg} onClick=${() => setQ(2)}>② what you want to do</button></div>
        <h2 id="qh">${q === 2 ? "What do you want to be able to do?" : "Where are you starting from?"}</h2>
        <p class="qhint">${q === 2 ? "tick as many as you like" : "pick one"}</p>
        <div class="picks" role=${q === 2 ? "group" : "radiogroup"} aria-labelledby="qh">
          ${list.map((o) => html`<button key=${o.id} class=${"pick" + (isOn(o.id) ? " pick-on" : "")} role=${q === 2 ? "checkbox" : "radio"} aria-checked=${isOn(o.id)} onClick=${() => pick(o.id)}>
            <span class=${"circ" + (q === 2 ? " sq" : "")} aria-hidden="true">${isOn(o.id) ? "✓" : ""}</span><span><b>${o.n}</b><span class="d">${o.b}</span></span></button>`)}
        </div>
        <div class="qfoot">
          ${q === 2 ? html`<button class="linkish" onClick=${() => setQ(1)}>‹ Back</button>` : html`<span></span>`}
          <button class="am-button" disabled=${q === 1 ? !bg : !goals.length} onClick=${go}>${q === 1 ? "Next question →" : goals.length ? `Show my ${P.steps.length} lessons →` : "Pick at least one"}</button>
        </div>
      </section>
      <aside class="mapwrap" aria-label="The course map, lighting up as you answer">
        <div class="cork cork-sm"><${CourseMap} D=${D} known=${bgObj ? bgObj.k : []} goals=${q === 2 ? goals : []} steps=${q === 2 ? P.steps : []} /></div>
        <${Legend} items=${[["gl-k", "you know it"], ["gl-p", "your lessons"], ["gl-g", "your goal"]]} />
        <p class="gcap">${caption}</p>
      </aside>
    </div>
  </main>`;
}

function Home({ D, S, P }) {
  const i = Math.min(S.i, P.steps.length - 1), c = D.C[P.steps[i]], learned = P.steps.filter((id) => S.done[id]).length;
  return html`<main class="home">
    <section class="card homecard">
      <span class="kicker">${S.started ? "Welcome back" : "Your path is ready"} · ${goalsLabel(D, S.goal)}</span>
      <h1>${c.n}</h1>
      <p>${c.s}</p>
      <div class="row"><a class="am-button" href=${"#/lesson/" + (i + 1)}>${S.started ? "Continue" : "Start"} lesson ${i + 1} of ${P.steps.length} →</a>
        <a class="linkish" href="#/path">See the whole path</a><a class="linkish" href="#/start">Change goals</a></div>
      <div class="bar" aria-label=${learned + " of " + P.steps.length + " lessons passed"}><span style=${{ width: (100 * learned) / P.steps.length + "%" }}></span></div>
      <small>${learned} of ${P.steps.length} lessons passed</small>
    </section>
    <div class="cork cork-sm home-map"><${CourseMap} D=${D} known=${P.known} goals=${S.goal} steps=${P.steps} current=${i} done=${S.done} onPick=${(k) => nav("#/lesson/" + (k + 1))} /></div>
  </main>`;
}

// The path as a corkboard of index cards with red string through your lessons.
function PathPage({ D, S, P, set }) {
  const C = D.C, pos = {}, known = new Set(P.known), i = Math.min(S.i, P.steps.length - 1);
  P.steps.forEach((id, k) => (pos[id] = k));
  const [open, setOpen] = useState({}), [note, setNote] = useState(null);
  const pinning = S.justBuilt && Date.now() - S.justBuilt < 4000 && !reduceMotion();
  const inner = useRef(), [str, setStr] = useState({ d: "", pins: [], w: 0, h: 0 });
  useLayoutEffect(() => {
    const draw = () => {
      const el = inner.current; if (!el) return;
      const o = el.getBoundingClientRect();
      const pts = [...el.querySelectorAll(".chip[data-n]")].sort((a, b) => a.dataset.n - b.dataset.n)
        .map((n) => { const r = n.getBoundingClientRect(); return [r.left - o.left + 22, r.top - o.top + r.height / 2]; });
      let d = "";
      pts.forEach(([x, y], k) => { if (!k) { d = `M${x},${y}`; return; } const [px, py] = pts[k - 1], dist = Math.hypot(x - px, y - py);
        d += ` Q${(px + x) / 2},${Math.max(py, y) + 6 + dist * 0.14} ${x},${y}`; });
      setStr({ d, pins: pts, w: el.scrollWidth, h: el.scrollHeight });
    };
    draw(); const on = () => requestAnimationFrame(draw);
    addEventListener("resize", on); document.fonts && document.fonts.ready.then(on);
    return () => removeEventListener("resize", on);
  }, [P.steps.join(), JSON.stringify(open)]);
  const cols = D.PARTS.map((p, ci) => {
    const ids = Object.keys(C).filter((id) => p.chs.includes(C[id].c)), onPath = ids.some((id) => id in pos), shown = onPath || open[ci];
    return html`<div key=${ci} class=${"col" + (shown ? "" : " col-closed")}>
      <div class="colsub">${ci === 0 ? "MATH THE BOOK ASSUMES" : "PART " + ["I", "II", "III", "IV"][ci - 1]}</div><div class="coltitle">${p.t}</div>
      ${shown ? p.chs.map((n) => { const items = ids.filter((id) => C[id].c === n); if (!items.length) return null;
        return html`<div key=${"ch" + n} class="chgroup">${n != null ? html`<div class="chl">${n === 0 ? "GETTING STARTED" : trunc("CH " + n + " · " + D.CH[n].title.toUpperCase(), 32)}</div>` : null}
          ${items.map((id) => html`<button key=${id} data-n=${id in pos ? pos[id] : null} style=${id in pos ? { "--n": pos[id] } : null} title=${C[id].n}
            class=${"chip " + (S.goal.includes(id) ? "chip-goal" : id in pos ? "chip-path" + (S.done[id] ? " chip-done" : "") : known.has(id) ? "chip-known" : "chip-dim")}
            onClick=${() => setNote(id)}><span class="num">${id in pos ? pos[id] + 1 : ""}</span><span class="nm">${trunc(C[id].n, 26)}</span></button>`)}</div>`; })
      : html`<button class="showcol" onClick=${() => setOpen({ ...open, [ci]: true })}>${ids.length} concepts, not on this path. Show</button>`}
    </div>`;
  });
  const nc = note && C[note];
  return html`<main class="pathpage">
    <section class="card pathlist" aria-labelledby="ph">
      <span class="kicker">Your path · from ${(D.BG.find((b) => b.id === S.bg) || {}).n}</span>
      <h1 id="ph">${goalsLabel(D, S.goal)}</h1>
      <ol>${P.steps.map((id, k) => html`<li key=${id}><a href=${"#/lesson/" + (k + 1)} class=${"step" + (S.done[id] ? " step-done" : "") + (k === i && S.started ? " step-now" : "")}>
        <span class="sn">${S.done[id] ? "✓" : k + 1}</span><span><span class="sname">${C[id].n}</span><span class="smeta">${C[id].c == null ? "background" : "chapter " + C[id].c}${C[id].L.length ? " · lecture" : ""}${C[id].N.length ? " · notebook" : ""}</span></span></a></li>`)}</ol>
      <div class="row"><a class="am-button" href=${"#/lesson/" + (i + 1)}>${S.started ? "Continue lesson " + (i + 1) : "Start lesson 1"} →</a><a class="linkish" href="#/start">Change goals</a></div>
    </section>
    <section class=${"cork cork-board" + (pinning ? " pinning" : "")} aria-labelledby="mh">
      <div class="cork-head"><h2 id="mh" class="paper-label">Where your path goes</h2>
        <${Legend} items=${[["lg-path", "your lessons, pinned in order"], ["lg-goal", "goal"], ["lg-known", "you know it"]]} /></div>
      ${nc ? html`<div class="notecard"><div><b>${nc.n}</b><span>${chName(D, nc.c)} · ${note in pos ? "lesson " + (pos[note] + 1) + " on your path" : known.has(note) ? "you already know this" : pathFor(D, S.bg, [note]).steps.length + " lessons from where you are"}</span></div>
        <div class="row">${note in pos ? html`<a class="am-button" href=${"#/lesson/" + (pos[note] + 1)}>Open lesson</a>` : !S.goal.includes(note) ? html`<button class="am-button am--secondary" onClick=${() => { setNote(null); set({ goal: S.goal.concat(note), i: 0, started: false }); }}>Add as a goal</button>` : null}
          <button class="linkish" onClick=${() => setNote(null)}>Close</button></div></div>` : null}
      <div class="cork-scroll"><div class="cork-in" ref=${inner}>${cols}
        <svg class="string" width=${str.w} height=${str.h} aria-hidden="true">
          <path d=${str.d} class="str-shadow" pathLength="1" /><path d=${str.d} class="str-line" pathLength="1" />
          ${str.pins.map(([x, y], k) => html`<g key=${k} class="pin"><circle cx=${x} cy=${y + 1.5} r="5" fill="rgba(0,0,0,.3)" /><circle cx=${x} cy=${y} r="4.6" fill="#d6332a" /><circle cx=${x - 1.4} cy=${y - 1.6} r="1.5" fill="#ff9a8f" /></g>`)}
        </svg></div></div>
      <p class="paper-tip">Follow the red string. Tap a card to see where it sits.</p>
    </section>
  </main>`;
}

function Lesson({ D, S, P, set, n }) {
  const C = D.C, steps = P.steps, total = steps.length, i = Math.max(0, Math.min(n, total - 1)), id = steps[i], c = C[id];
  const prev = i > 0 ? C[steps[i - 1]] : null, next = i < total - 1 ? C[steps[i + 1]] : null;
  const [picked, setPicked] = useState(null), [checked, setChecked] = useState(false), [playing, setPlaying] = useState(false), [pulse, setPulse] = useState(null);
  useEffect(() => { setPicked(null); setChecked(false); setPlaying(false); if (S.i !== i || !S.started) set({ i, started: true }); window.scrollTo(0, 0); }, [id]);
  const [qq, choices, correct, why] = c.q, ok = picked === correct;
  const check = () => {
    setChecked(true);
    const wrong = { ...S.wrong }; if (ok) delete wrong[id]; else wrong[id] = { at: S.tick + 1 };
    set({ done: ok ? { ...S.done, [id]: true } : S.done, passed: S.passed + (ok ? 1 : 0), wrong, tick: S.tick + 1 });
    if (ok && next) setPulse({ from: i, key: Date.now() });
  };
  const L = c.L[0], nbk = c.N[0], ch = c.c == null ? null : D.CH[c.c];
  const yt = L && (String(L.url).match(/(?:youtu\.be\/|v=|embed\/)([\w-]{11})/) || [])[1];
  const kicker = c.c == null ? "Background the book assumes" : c.c === 0 ? "Getting started" : "Chapter " + c.c + " · " + ch.title;
  const retry = Object.keys(S.wrong || {}).filter((w) => steps.includes(w));
  const noted = steps.filter((k) => ((S.notes || {})[k] || "").trim()).length;
  const go = (k) => nav("#/lesson/" + (k + 1));
  return html`<main class="lesson">
    <div class="lessonbar">
      <a class="navarrow" href=${prev ? "#/lesson/" + i : null} aria-disabled=${!prev} aria-label="Previous lesson">‹</a>
      <div class="lb-mid"><span class="lb-t">Lesson ${i + 1} of ${total} · <a href="#/path">${goalsLabel(D, S.goal)}</a></span>
        <ol class="segs" aria-label="Lessons on this path">${steps.map((sid, k) => html`<li key=${sid}><a href=${"#/lesson/" + (k + 1)} title=${k + 1 + ". " + C[sid].n} aria-label=${"Lesson " + (k + 1) + ": " + C[sid].n}
          class=${"seg" + (k === i ? " seg-on" : S.done[sid] ? " seg-done" : "")} aria-current=${k === i ? "step" : null}></a></li>`)}</ol></div>
      <a class="navarrow" href=${next ? "#/lesson/" + (i + 2) : "#/done"} aria-label=${next ? "Next lesson" : "Finish"}>›</a>
    </div>
    <div class="lesson-grid" key=${id}>
      <div class="lesson-main">
        <section class="board" data-medium="charcoal" data-theme="dark" aria-labelledby="lt">
          <div class="chalk"><span class="ch-kick">${kicker}</span>
          <h1 id="lt" class="ch-title">${c.n}</h1>
          <p class="ch-sum">${c.s}</p></div>
          ${L ? html`<figure class="video">
              <div class="screen">${playing && yt ? html`<iframe src=${`https://www.youtube-nocookie.com/embed/${yt}?autoplay=1&rel=0&modestbranding=1`} title=${L.title} allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`
                : html`<button class="play" onClick=${() => setPlaying(true)} aria-label=${"Play " + L.title} style=${yt ? { backgroundImage: `url(https://i.ytimg.com/vi/${yt}/hqdefault.jpg)` } : null}><span>▶</span></button>`}</div>
              <figcaption class="chalk">Stanford ${L.course} · lecture ${L.n}: ${L.title} <a href=${L.url} target="_blank" rel="noopener">open on YouTube ↗</a></figcaption></figure>`
            : html`<p class="ch-note">No lecture covers this one. The key ideas and the chapter below have it.</p>`}
          <div class="chalk"><h2 class="ch-h">Key ideas</h2>
          <ol class="ideas">${c.i.map((t, k) => html`<li key=${k}>${t}</li>`)}</ol></div>
        </section>

        <section class="card quiz" aria-labelledby="qz">
          <h2 id="qz">Check yourself</h2>
          <p class="qq">${qq}</p>
          <div role="radiogroup" aria-labelledby="qz" class="qopts">${choices.map((t, k) => {
            const cls = checked ? (k === correct ? " qopt-right" : k === picked ? " qopt-wrong" : "") : picked === k ? " qopt-on" : "";
            return html`<button key=${k} class=${"qopt" + cls} role="radio" aria-checked=${picked === k} disabled=${checked} onClick=${() => setPicked(k)}>
              <span class="qm">${checked && k === correct ? "✓" : checked && k === picked ? "✗" : "ABCD"[k]}</span><span>${t}</span></button>`; })}</div>
          ${checked ? html`<div class=${"feedback " + (ok ? "fb-ok" : "fb-no")} role="status"><b>${ok ? "Right." : "Not quite."}</b> ${why}${ok ? "" : html` <em>It's on your retry list for later.</em>`}</div>` : null}
          <div class="row">
            ${!checked ? html`<button class="am-button" disabled=${picked === null} onClick=${check}>Check answer</button>`
              : html`<a class="am-button" href=${next ? "#/lesson/" + (i + 2) : "#/done"}>${next ? "Next: " + trunc(next.n, 32) + " →" : "Finish the path ★"}</a>
                ${!ok ? html`<button class="linkish" onClick=${() => { setChecked(false); setPicked(null); }}>Try again</button>` : null}`}
            ${!checked && next ? html`<a class="linkish" href=${"#/lesson/" + (i + 2)}>Skip for now</a>` : null}
          </div>
        </section>

        <section class="card practice" aria-labelledby="pr">
          <h2 id="pr">Practice</h2>
          <p>${c.t}</p>
          <div class="row">
            ${nbk ? html`<a class="am-button am--secondary" href=${nbk.colab} target="_blank" rel="noopener">Open the ${nbk.title} notebook in Colab ↗</a>` : null}
            <a class="linkish" href=${ch ? ch.url : "https://porabook.com/book/"} target="_blank" rel="noopener">Read ${c.c == null ? "the book" : "chapter " + c.c} on porabook.com ↗</a>
          </div>
        </section>
      </div>

      <aside class="lesson-side">
        <section class="card side-map" aria-labelledby="ym">
          <div class="side-head"><h2 id="ym">Your map</h2><span>${P.steps.filter((x) => S.done[x]).length} of ${total} passed</span></div>
          <div class="cork cork-xs"><${CourseMap} D=${D} known=${P.known} goals=${S.goal} steps=${steps} current=${i} done=${S.done} compact pulse=${pulse} onPick=${go} /></div>
          <${Legend} items=${[["gl-now", "you're here"], ["gl-d", "passed"], ["gl-p", "to do"], ["gl-g", "goal"]]} />
        </section>

        <section class="card notes" aria-labelledby="nt">
          <div class="side-head"><h2 id="nt"><label for="mynotes">Your notes</label></h2>${noted ? html`<button class="linkish" onClick=${() => exportNotes(D, S, steps)}>Export all (${noted}) ↓</button>` : null}</div>
          <textarea id="mynotes" class="ruled" placeholder="What clicked? What didn't? Saved as you type." value=${(S.notes || {})[id] || ""}
            onInput=${(e) => set({ notes: { ...S.notes, [id]: e.currentTarget.value } })}></textarea>
        </section>

        ${retry.length ? html`<section class="card retry" aria-labelledby="rt"><h2 id="rt">Retry later</h2>
          <p class="hint">Questions you missed come back after two more lessons.</p>
          <div class="stickies">${retry.map((w, k) => { const ago = S.tick - S.wrong[w].at, due = ago >= 2;
            return html`<a key=${w} href=${"#/lesson/" + (steps.indexOf(w) + 1)} class=${"sticky" + (due ? " sticky-due" : "")} style=${{ rotate: [-3, 2, -1.5, 3][k % 4] + "deg" }}>
              <span>${due ? "retry now" : "in " + (2 - ago) + " lesson" + (2 - ago > 1 ? "s" : "")}</span>${trunc(C[w].n, 40)}</a>`; })}</div></section>` : null}

        <section class="card research" aria-labelledby="rs">
          <h2 id="rs">Beyond the course</h2>
          ${(c.R || []).length ? html`<p class="hint">Recent papers from Brain University's research feed:</p>
            <ul>${c.R.map((r) => html`<li key=${r.u}><a href=${r.u} target="_blank" rel="noopener">${r.t}</a>${r.y ? html` <small>${r.y}</small>` : null}</li>`)}</ul>` : null}
          <a class="linkish" href=${arxivSearch(c.n)} target="_blank" rel="noopener">Search arXiv for the newest work on ${c.n} ↗</a>
          <a class="linkish" href="Brain%20University.html">See ${c.n} in the full Brain University graph →</a>
        </section>
      </aside>
    </div>
  </main>`;
}

function exportNotes(D, S, steps) {
  const ids = steps.filter((k) => ((S.notes || {})[k] || "").trim());
  const md = `# BrainU notes: ${goalsLabel(D, S.goal)}\n\n` + ids.map((k) => `## ${D.C[k].n}\n\n${S.notes[k].trim()}\n`).join("\n");
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([md], { type: "text/markdown" })); a.download = "brainu-notes.md";
  document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
}

function Done({ D, S, P }) {
  const learned = P.steps.filter((id) => S.done[id]).length;
  const papers = [...new Map(P.steps.flatMap((id) => D.C[id].R || []).map((r) => [r.u, r])).values()].slice(0, 5);
  return html`<main class="home">
    <section class="card homecard">
      <span class="kicker">Path complete</span><h1>${goalsLabel(D, S.goal)}</h1>
      <p>You worked through ${P.steps.length} lessons and passed ${learned} checks first time or on retry.</p>
      ${papers.length ? html`<h2>Where the research is now</h2><ul class="plist">${papers.map((r) => html`<li key=${r.u}><a href=${r.u} target="_blank" rel="noopener">${r.t}</a></li>`)}</ul>` : null}
      <div class="row"><a class="am-button" href="#/start">Pick new goals</a><a class="linkish" href="#/path">Back to my path</a></div>
    </section></main>`;
}

function Explore() {
  const items = [["The full Brain University app", "The knowledge graph, arXivis papers, open problems and podcasts.", "Brain%20University.html"],
    ["The course atlas", "Every PoRA concept and how they connect, on one page.", "courses/pora-atlas.html"],
    ["Principles of Robot Autonomy", "The book, lectures and exercises, free from Stanford.", "https://porabook.com"],
    ["The classroom prototype", "The earlier chalkboard-and-desk version of this companion.", "classroom.html"]];
  return html`<main class="explore"><h1>Explore</h1>
    <div class="egrid">${items.map(([t, d, u]) => html`<a key=${t} class="card ecard" href=${u} target=${u.startsWith("http") ? "_blank" : null} rel="noopener"><h2>${t}</h2><p>${d}</p></a>`)}</div></main>`;
}

// ── app ─────────────────────────────────────────────────────────────
function load() {
  const S = { bg: null, goal: null, started: false, i: 0, done: {}, passed: 0, notes: {}, wrong: {}, tick: 0, justBuilt: 0 };
  try { const s = JSON.parse(localStorage.getItem(KEY) || "null"); if (s) SAVED.forEach((k) => { if (k in s) S[k] = s[k]; }); } catch (e) {}
  if (typeof S.goal === "string") S.goal = [S.goal];
  if (S.goal && !S.goal.length) S.goal = null;
  return S;
}

function App() {
  const [D, setD] = useState(null), [err, setErr] = useState(false), [S, setS] = useState(load), [route, setRoute] = useState(parse());
  useEffect(() => {
    fetch("prototype/course.json").then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); }).then(setD).catch(() => setErr(true));
    const on = () => setRoute(parse()); addEventListener("hashchange", on); return () => removeEventListener("hashchange", on);
  }, []);
  const set = (patch) => setS((s) => { const n = { ...s, ...patch }; try { const o = {}; SAVED.forEach((k) => (o[k] = n[k])); localStorage.setItem(KEY, JSON.stringify(o)); } catch (e) {} return n; });
  useEffect(() => { window.scrollTo(0, 0); }, [route.page]);
  if (err) return html`<p class="loading">The course didn't load. Run a local server in the design folder (python3 -m http.server 8000) and reload.</p>`;
  if (!D) return html`<p class="loading">Loading the course…</p>`;
  const goals = (S.goal || []).filter((g) => D.C[g]), hasPath = !!(S.bg && goals.length);
  const P = hasPath ? pathFor(D, S.bg, goals) : null, s = { ...S, goal: goals };
  let page = route.page, body;
  if (page === "explore") body = html`<${Explore} />`;
  else if (page === "start" || !hasPath) { page = page === "start" ? "start" : ""; body = html`<${Start} D=${D} S=${s} set=${set} />`; }
  else if (page === "path") body = html`<${PathPage} D=${D} S=${s} P=${P} set=${set} />`;
  else if (page === "lesson") body = html`<${Lesson} D=${D} S=${s} P=${P} set=${set} n=${route.arg ? parseInt(route.arg, 10) - 1 || 0 : Math.min(S.i, P.steps.length - 1)} />`;
  else if (page === "done") body = html`<${Done} D=${D} S=${s} P=${P} />`;
  else body = html`<${Home} D=${D} S=${s} P=${P} />`;
  return html`<${TopNav} page=${page} hasPath=${hasPath} />${body}`;
}

render(html`<${App} />`, document.getElementById("app"));
